package android.os;import java.util.*;
public class Binder implements IBinder {public static int uid=2000;public static int getCallingUid(){return uid;}public static long clearCallingIdentity(){return uid;}public static void restoreCallingIdentity(long id){}public boolean alive=true;public List<DeathRecipient> deaths=new ArrayList<>();public boolean isBinderAlive(){return alive;}public void linkToDeath(DeathRecipient death,int flags)throws RemoteException{deaths.add(death);}public void die(){alive=false;deaths.forEach(DeathRecipient::binderDied);}public boolean transact(int code,Parcel data,Parcel reply,int flags)throws RemoteException {return onTransact(code,data,reply,flags);}protected boolean onTransact(int code,Parcel data,Parcel reply,int flags)throws RemoteException{return false;}}
